import Foundation

/// Model representing an ACA $0 preventive care medication mandated by federal law
struct ACAPreventiveMedication: Identifiable, Codable, Hashable, Sendable {
    let id: String
    let name: String
    let brandName: String?
    let genericName: String
    let category: String
    let subcategory: String
    let details: String
    let monthlyCost: Double

    var isACAEligible: Bool { true }

    func matches(query: String) -> Bool {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !trimmed.isEmpty else { return false }
        if name.localizedCaseInsensitiveContains(trimmed) { return true }
        if genericName.localizedCaseInsensitiveContains(trimmed) { return true }
        if let brandName, brandName.localizedCaseInsensitiveContains(trimmed) { return true }
        if category.localizedCaseInsensitiveContains(trimmed) { return true }
        if subcategory.localizedCaseInsensitiveContains(trimmed) { return true }
        return false
    }
}

