    /// Returns in-line predictive suggestions matching the typed text
    static func suggestions(for query: String, limit: Int = 5) -> [ACAPreventiveMedication] {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !trimmed.isEmpty else { return [] }
        // Prioritize exact prefix match on display name or brand name, then contains
        var prefixMatches: [ACAPreventiveMedication] = []
        var otherMatches: [ACAPreventiveMedication] = []

        for med in medications {
            let medName = med.name.lowercased()
            let brand = med.brandName?.lowercased() ?? ""
            let gen = med.genericName.lowercased()

            if medName.hasPrefix(trimmed) || brand.hasPrefix(trimmed) || gen.hasPrefix(trimmed) {
                prefixMatches.append(med)
            } else if medName.contains(trimmed) || brand.contains(trimmed) || gen.contains(trimmed) {
                otherMatches.append(med)
            }
            if prefixMatches.count >= limit { break }
        }

        let combined = prefixMatches + otherMatches
        return Array(combined.prefix(limit))
    }

    /// Checks if a medication matches any item in the ACA $0 list
    static func findMatch(for query: String) -> ACAPreventiveMedication? {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !trimmed.isEmpty else { return nil }
        return medications.first { med in
            med.name.localizedCaseInsensitiveCompare(trimmed) == .orderedSame ||
            med.brandName?.localizedCaseInsensitiveCompare(trimmed) == .orderedSame ||
            trimmed.hasPrefix(med.name.lowercased()) ||
            med.name.lowercased().hasPrefix(trimmed) ||
            (med.brandName != nil && trimmed.contains(med.brandName!.lowercased())) ||
            trimmed.contains(med.genericName.lowercased())
        }
    }

    static func isACAPreventive(name: String) -> Bool {
        findMatch(for: name) != nil
    }
